import { TriviaQuestion } from '../trivia-types'

export const FOOD_DRINK_QUESTIONS: TriviaQuestion[] = [
  { id: 'food-1', category: 'food-drink', difficulty: 'easy', question: 'What spirit is the primary ingredient in a margarita?', answer: 'Tequila', options: ['Rum', 'Tequila', 'Vodka', 'Gin'], explanation: 'A classic margarita is made with tequila, lime juice, and orange liqueur (such as Cointreau or triple sec). Tequila is made from the blue agave plant and must be produced in specific regions of Mexico.' },
  { id: 'food-2', category: 'food-drink', difficulty: 'easy', question: 'What country is the origin of sushi?', answer: 'Japan', options: ['China', 'Japan', 'Korea', 'Thailand'], explanation: 'While an early form of fermented fish and rice originated in Southeast Asia, modern sushi as we know it developed in Japan. Hanaya Yohei is often credited with creating Edo-style nigiri sushi in Tokyo in the 1820s.' },
  { id: 'food-3', category: 'food-drink', difficulty: 'easy', question: 'What type of pasta is shaped like small tubes?', answer: 'Penne', options: ['Spaghetti', 'Penne', 'Linguine', 'Fettuccine'], explanation: 'Penne gets its name from the Italian word "penna" meaning quill or feather pen, due to its angled cut resembling a pen nib. The ridged version is called penne rigate, which holds sauce better.' },
  { id: 'food-4', category: 'food-drink', difficulty: 'easy', question: 'What is the main ingredient in guacamole?', answer: 'Avocado', options: ['Tomato', 'Avocado', 'Green pepper', 'Lime'], explanation: 'Guacamole originated with the Aztecs in what is now Mexico. The word comes from the Nahuatl "ahuacamolli," combining "ahuacatl" (avocado) and "molli" (sauce).' },
  { id: 'food-5', category: 'food-drink', difficulty: 'easy', question: 'What fast food chain is known for its "Big Mac"?', answer: 'McDonald\'s', options: ['Burger King', 'McDonald\'s', 'Wendy\'s', 'Five Guys'], explanation: 'The Big Mac was created by Jim Delligatti, a McDonald\'s franchisee in Uniontown, Pennsylvania, in 1967. It went nationwide in 1968 and has become one of the most recognizable sandwiches in the world.' },
  { id: 'food-6', category: 'food-drink', difficulty: 'easy', question: 'What country is Parmesan cheese originally from?', answer: 'Italy', options: ['France', 'Italy', 'Switzerland', 'Spain'], explanation: 'Parmigiano-Reggiano comes from the Parma and Reggio Emilia provinces of Italy. True Parmigiano-Reggiano has a Protected Designation of Origin (PDO) and must be aged for a minimum of 12 months.' },
  { id: 'food-7', category: 'food-drink', difficulty: 'easy', question: 'What spice gives curry its yellow color?', answer: 'Turmeric', options: ['Saffron', 'Turmeric', 'Cumin', 'Paprika'], explanation: 'Turmeric contains curcumin, the compound responsible for its bright yellow color. India produces over 80% of the world\'s turmeric supply, and the spice has been used for thousands of years in cooking and medicine.' },
  { id: 'food-8', category: 'food-drink', difficulty: 'easy', question: 'What is the most consumed beverage in the world after water?', answer: 'Tea', options: ['Coffee', 'Tea', 'Beer', 'Milk'], explanation: 'Tea is consumed by two-thirds of the world\'s population. Legend credits Chinese Emperor Shen Nung with discovering tea in 2737 BC when leaves blew into his pot of boiling water.' },
  { id: 'food-9', category: 'food-drink', difficulty: 'easy', question: 'What cocktail is made with vodka and orange juice?', answer: 'Screwdriver', options: ['Mimosa', 'Tequila Sunrise', 'Screwdriver', 'Harvey Wallbanger'], explanation: 'The Screwdriver gets its name from American oil workers in the Persian Gulf in the mid-20th century who allegedly stirred the drink with a screwdriver. A Harvey Wallbanger is a Screwdriver with Galliano added.' },
  { id: 'food-10', category: 'food-drink', difficulty: 'easy', question: 'What grain is beer primarily made from?', answer: 'Barley', options: ['Wheat', 'Barley', 'Corn', 'Rice'], explanation: 'Barley is the most common grain used in brewing because its high enzyme content efficiently converts starch to sugar during mashing. The German Reinheitsgebot (Beer Purity Law) of 1516 allowed only barley, hops, and water.' },
  { id: 'food-11', category: 'food-drink', difficulty: 'easy', question: 'What Italian dish is made of layers of pasta, meat sauce, and cheese?', answer: 'Lasagna', options: ['Ravioli', 'Lasagna', 'Manicotti', 'Cannelloni'], explanation: 'Lasagna is one of the oldest pasta dishes, with origins in ancient Rome or Greece. The traditional Bolognese version uses bechamel sauce and ragu, while the Neapolitan version uses ricotta and mozzarella.' },
  { id: 'food-12', category: 'food-drink', difficulty: 'easy', question: 'What fruit is traditionally used to make wine?', answer: 'Grapes', options: ['Apples', 'Grapes', 'Berries', 'Plums'], explanation: 'Grapes are ideal for winemaking because they naturally contain the right balance of sugars, acids, and tannins for fermentation. The oldest known winery, dating to about 4100 BC, was discovered in Armenia.' },
  { id: 'food-13', category: 'food-drink', difficulty: 'easy', question: 'What is tofu made from?', answer: 'Soybeans', options: ['Rice', 'Soybeans', 'Wheat', 'Lentils'], explanation: 'Tofu is made by coagulating soy milk and pressing the resulting curds into blocks. It was invented in China during the Han Dynasty, around 200 BC, and spread throughout East Asia over the following centuries.' },
  { id: 'food-14', category: 'food-drink', difficulty: 'easy', question: 'What country is the origin of croissants?', answer: 'Austria', options: ['France', 'Austria', 'Italy', 'Belgium'], explanation: 'The croissant evolved from the Austrian kipferl, a crescent-shaped pastry. French bakers adopted it in the 19th century and refined the recipe using laminated dough to create the flaky version we know today.' },
  { id: 'food-15', category: 'food-drink', difficulty: 'easy', question: 'What cocktail consists of rum, lime juice, sugar, mint, and soda water?', answer: 'Mojito', options: ['Daiquiri', 'Mojito', 'Caipirinha', 'Mai Tai'], explanation: 'The Mojito originated in Havana, Cuba, and has roots dating back to the 16th century. Ernest Hemingway was a famous fan, reportedly drinking them at La Bodeguita del Medio bar in Havana.' },
  { id: 'food-16', category: 'food-drink', difficulty: 'easy', question: 'What type of cheese is traditionally used on pizza in Italy?', answer: 'Mozzarella', options: ['Cheddar', 'Mozzarella', 'Provolone', 'Parmesan'], explanation: 'Traditional Italian pizza uses mozzarella, ideally mozzarella di bufala (from water buffalo milk). The Margherita pizza, topped with mozzarella, tomato, and basil, is said to represent the Italian flag\'s colors.' },
  { id: 'food-17', category: 'food-drink', difficulty: 'easy', question: 'What is the most expensive spice in the world by weight?', answer: 'Saffron', options: ['Vanilla', 'Saffron', 'Cardamom', 'Turmeric'], explanation: 'Saffron costs $5,000 to $10,000 per pound because each crocus flower produces only three stigmas, and it takes about 75,000 flowers to yield one pound. Iran produces roughly 90% of the world\'s saffron.' },
  { id: 'food-18', category: 'food-drink', difficulty: 'easy', question: 'What Japanese spirit is made from rice?', answer: 'Sake', options: ['Shochu', 'Sake', 'Soju', 'Baijiu'], explanation: 'Sake is brewed through a unique process where rice starch is converted to sugar and then to alcohol simultaneously. Despite being called "rice wine," its brewing process is closer to beer than wine.' },
  { id: 'food-19', category: 'food-drink', difficulty: 'easy', question: 'What country is feta cheese from?', answer: 'Greece', options: ['Turkey', 'Greece', 'Italy', 'Bulgaria'], explanation: 'Feta has been produced in Greece for thousands of years and has a Protected Designation of Origin in the EU, meaning only cheese made in specific Greek regions can legally be called feta.' },
  { id: 'food-20', category: 'food-drink', difficulty: 'easy', question: 'What nut is used to make marzipan?', answer: 'Almonds', options: ['Hazelnuts', 'Almonds', 'Pistachios', 'Walnuts'], explanation: 'Marzipan is made from ground almonds, sugar, and sometimes egg whites. It is popular in European confectionery, particularly in Germany (where it is a Christmas tradition) and the Mediterranean.' },
  { id: 'food-21', category: 'food-drink', difficulty: 'easy', question: 'What cooking technique involves submerging food in hot oil?', answer: 'Deep frying', options: ['Sauteing', 'Deep frying', 'Broiling', 'Braising'], explanation: 'Deep frying cooks food by immersing it completely in oil heated to 325-375°F. The technique has ancient origins — frying in oil was practiced in ancient Egypt, Greece, and Rome.' },
  { id: 'food-22', category: 'food-drink', difficulty: 'easy', question: 'What classic cocktail is made with gin, vermouth, and an olive?', answer: 'Martini', options: ['Manhattan', 'Martini', 'Gibson', 'Negroni'], explanation: 'The Martini is one of the most iconic cocktails, traditionally made with gin and dry vermouth. James Bond famously orders his "shaken, not stirred," though most bartenders prefer to stir a Martini.' },
  { id: 'food-23', category: 'food-drink', difficulty: 'easy', question: 'What is the primary ingredient in hummus?', answer: 'Chickpeas', options: ['Lentils', 'Chickpeas', 'White beans', 'Fava beans'], explanation: 'Hummus is made from mashed chickpeas blended with tahini, lemon juice, garlic, and olive oil. The word "hummus" simply means "chickpeas" in Arabic, and the dish has been eaten in the Middle East for centuries.' },
  { id: 'food-24', category: 'food-drink', difficulty: 'easy', question: 'What country does the dish paella come from?', answer: 'Spain', options: ['Mexico', 'Spain', 'Portugal', 'Italy'], explanation: 'Paella originated in Valencia, Spain, and traditionally features rice, saffron, rabbit, chicken, and snails. The word "paella" comes from the Latin "patella" meaning pan, referring to the wide shallow dish it is cooked in.' },
  { id: 'food-25', category: 'food-drink', difficulty: 'easy', question: 'What berry is used to flavor gin?', answer: 'Juniper', options: ['Elderberry', 'Juniper', 'Blueberry', 'Blackberry'], explanation: 'Juniper berries are the defining botanical in gin — by law, gin must have juniper as its predominant flavor. The word "gin" comes from the Dutch "jenever," which derives from the Latin "juniperus."' },
  { id: 'food-26', category: 'food-drink', difficulty: 'easy', question: 'What type of milk is traditionally used to make Indian chai?', answer: 'Whole milk', options: ['Skim milk', 'Whole milk', 'Coconut milk', 'Almond milk'], explanation: 'Traditional Indian masala chai is made by simmering tea with whole milk, sugar, and spices like cardamom, cinnamon, ginger, and cloves. The word "chai" simply means "tea" in Hindi, so "chai tea" is redundant.' },
  { id: 'food-27', category: 'food-drink', difficulty: 'easy', question: 'What fast food chain was founded by Colonel Harland Sanders?', answer: 'KFC', options: ['Popeyes', 'KFC', 'Chick-fil-A', 'Church\'s Chicken'], explanation: 'Harland Sanders began selling fried chicken from his roadside restaurant in Corbin, Kentucky, during the Great Depression. He franchised KFC (Kentucky Fried Chicken) in 1952 at the age of 62.' },
  { id: 'food-28', category: 'food-drink', difficulty: 'easy', question: 'What Mexican dish consists of a folded tortilla filled with meat, cheese, and vegetables?', answer: 'Taco', options: ['Burrito', 'Taco', 'Enchilada', 'Quesadilla'], explanation: 'The taco predates the arrival of Europeans in Mexico, with indigenous people using tortillas as edible utensils. The hard-shell taco popular in the US was popularized by Glen Bell, founder of Taco Bell, in the 1950s.' },
  { id: 'food-29', category: 'food-drink', difficulty: 'easy', question: 'What is the world\'s most popular candy bar?', answer: 'Snickers', options: ['Kit Kat', 'Snickers', 'Twix', 'Milky Way'], explanation: 'Snickers has been the world\'s best-selling candy bar for decades, with annual sales exceeding $2 billion. Introduced in 1930 by Mars, Inc., it was named after the Mars family\'s favorite horse.' },
  { id: 'food-30', category: 'food-drink', difficulty: 'easy', question: 'What French sauce is made from butter, egg yolks, and lemon juice?', answer: 'Hollandaise', options: ['Bearnaise', 'Hollandaise', 'Bechamel', 'Veloute'], explanation: 'Hollandaise is one of the five French mother sauces. Despite its name meaning "from Holland," it was codified in French cuisine. It is most famously served over eggs in Eggs Benedict.' },
  { id: 'food-31', category: 'food-drink', difficulty: 'easy', question: 'What country is the largest producer of coffee in the world?', answer: 'Brazil', options: ['Colombia', 'Vietnam', 'Brazil', 'Ethiopia'], explanation: 'Brazil has been the world\'s largest coffee producer for over 150 years, producing roughly one-third of the global supply. Coffee was introduced to Brazil in 1727 and quickly became the country\'s dominant crop.' },
  { id: 'food-32', category: 'food-drink', difficulty: 'easy', question: 'What cocktail is made with bourbon, sugar, bitters, and an orange peel?', answer: 'Old Fashioned', options: ['Manhattan', 'Old Fashioned', 'Whiskey Sour', 'Sazerac'], explanation: 'The Old Fashioned is one of the oldest cocktails, dating to the early 1800s. It was originally simply called a "whiskey cocktail" and got the name "Old Fashioned" when drinkers asked for the drink made "the old-fashioned way."' },
  { id: 'food-33', category: 'food-drink', difficulty: 'easy', question: 'What Italian cookie gets its name from the Italian word meaning "twice-baked"?', answer: 'Biscotti', options: ['Gelato', 'Biscotti', 'Amaretti', 'Pizzelle'], explanation: 'Biscotti literally means "twice-baked" (bis-cotti) in Italian. These Italian almond cookies are baked once as a log, sliced, then baked again to achieve their signature crunch.' },
  { id: 'food-34', category: 'food-drink', difficulty: 'easy', question: 'What type of Japanese restaurant features a rotating conveyor belt of sushi?', answer: 'Kaiten-zushi', options: ['Izakaya', 'Kaiten-zushi', 'Ramen-ya', 'Robatayaki'], explanation: 'Kaiten-zushi (conveyor belt sushi) was invented by Yoshiaki Shiraishi in Osaka in 1958. He was inspired by beer bottles moving on a conveyor belt at a brewery. The concept made sushi affordable for ordinary people.' },
  { id: 'food-35', category: 'food-drink', difficulty: 'medium', question: 'What cocktail is made with rye whiskey, sweet vermouth, and Angostura bitters?', answer: 'Manhattan', options: ['Manhattan', 'Old Fashioned', 'Sazerac', 'Rob Roy'], explanation: 'The Manhattan dates to the 1870s and was supposedly invented at the Manhattan Club in New York City. A Rob Roy is essentially the same cocktail but made with Scotch whisky instead of rye.' },
  { id: 'food-36', category: 'food-drink', difficulty: 'medium', question: 'What region of France is known for producing Champagne?', answer: 'Champagne', options: ['Burgundy', 'Bordeaux', 'Champagne', 'Alsace'], explanation: 'Only sparkling wine made in the Champagne region of northeastern France can legally be called Champagne. Dom Perignon, a Benedictine monk, is often credited with developing Champagne in the late 17th century, though this is somewhat mythologized.' },
  { id: 'food-37', category: 'food-drink', difficulty: 'medium', question: 'What is the main flavoring agent in a traditional Sazerac cocktail?', answer: 'Absinthe', options: ['Angostura bitters', 'Absinthe', 'Orange liqueur', 'Vermouth'], explanation: 'The Sazerac is one of America\'s oldest cocktails, originating in New Orleans in the mid-1800s. The glass is rinsed with absinthe (or a substitute like Herbsaint), then filled with rye whiskey, sugar, and Peychaud\'s bitters.' },
  { id: 'food-38', category: 'food-drink', difficulty: 'medium', question: 'What country produces the most wine in the world?', answer: 'Italy', options: ['France', 'Spain', 'Italy', 'United States'], explanation: 'Italy and France consistently trade the top spot, but Italy has been the world\'s largest wine producer in most recent years. Italy produces over 50 million hectoliters annually from its 20 wine-producing regions.' },
  { id: 'food-39', category: 'food-drink', difficulty: 'medium', question: 'What is the Japanese cooking technique of coating food in light batter and deep-frying it?', answer: 'Tempura', options: ['Katsu', 'Tempura', 'Karaage', 'Teriyaki'], explanation: 'Tempura was introduced to Japan by Portuguese missionaries in the 16th century. The word may derive from the Portuguese "tempero" (seasoning) or "tempora," referring to Lenten fasting periods when fried food was eaten.' },
  { id: 'food-40', category: 'food-drink', difficulty: 'medium', question: 'What type of whiskey must be made from at least 51% corn and aged in new charred oak barrels?', answer: 'Bourbon', options: ['Rye whiskey', 'Bourbon', 'Scotch whisky', 'Tennessee whiskey'], explanation: 'Bourbon does not have to be made in Kentucky, but roughly 95% of it is. By law, it must be made in the US, from at least 51% corn, aged in new charred oak barrels, distilled to no more than 160 proof, and entered into barrels at no more than 125 proof.' },
  { id: 'food-41', category: 'food-drink', difficulty: 'medium', question: 'What is the name of the French cooking technique of slowly cooking food in its own fat?', answer: 'Confit', options: ['Confit', 'Braise', 'Poach', 'Flambe'], explanation: 'Confit (from the French "confire," meaning to preserve) was originally a preservation method before refrigeration. Duck confit (confit de canard) is the most famous example, with duck legs slowly cooked in duck fat.' },
  { id: 'food-42', category: 'food-drink', difficulty: 'medium', question: 'What Italian coffee drink is made with espresso and steamed milk foam?', answer: 'Cappuccino', options: ['Latte', 'Cappuccino', 'Americano', 'Macchiato'], explanation: 'Cappuccino gets its name from the Capuchin friars, whose brown robes resembled the color of the drink. A traditional Italian cappuccino has equal parts espresso, steamed milk, and milk foam, and is typically only drunk in the morning.' },
  { id: 'food-43', category: 'food-drink', difficulty: 'medium', question: 'What French cheese is known as the "King of Cheeses"?', answer: 'Brie', options: ['Roquefort', 'Brie', 'Camembert', 'Comte'], explanation: 'Brie de Meaux was crowned "King of Cheeses" at a cheese competition during the Congress of Vienna in 1815, where it beat 60 other European cheeses. It is a soft, creamy cheese from the Ile-de-France region.' },
  { id: 'food-44', category: 'food-drink', difficulty: 'medium', question: 'What Mexican spirit is distilled from the agave plant and is the predecessor to tequila?', answer: 'Mezcal', options: ['Pulque', 'Mezcal', 'Sotol', 'Raicilla'], explanation: 'Mezcal is a broader category — all tequila is mezcal, but not all mezcal is tequila. Tequila must be made from blue agave in specific regions, while mezcal can be made from over 30 types of agave. Mezcal is traditionally known for its smoky flavor.' },
  { id: 'food-45', category: 'food-drink', difficulty: 'medium', question: 'What is the primary difference between a latte and a cappuccino?', answer: 'The ratio of milk to foam', options: ['The type of coffee bean', 'The ratio of milk to foam', 'The temperature', 'The number of espresso shots'], explanation: 'A latte has more steamed milk and a thin layer of foam, while a cappuccino has equal parts espresso, steamed milk, and thick foam. The word "latte" is Italian for "milk," so ordering a "latte" in Italy will get you a glass of plain milk.' },
  { id: 'food-46', category: 'food-drink', difficulty: 'medium', question: 'What chef is known as the "father of modern French cuisine"?', answer: 'Auguste Escoffier', options: ['Paul Bocuse', 'Auguste Escoffier', 'Marie-Antoine Careme', 'Fernand Point'], explanation: 'Escoffier (1846-1935) modernized and codified French cuisine, organizing the professional kitchen with the brigade system still used today. He simplified the elaborate cuisine of Careme and co-authored Le Guide Culinaire in 1903.' },
  { id: 'food-47', category: 'food-drink', difficulty: 'medium', question: 'What country is the origin of the cocktail called the Caipirinha?', answer: 'Brazil', options: ['Mexico', 'Brazil', 'Cuba', 'Portugal'], explanation: 'The Caipirinha is Brazil\'s national cocktail, made with cachaca (sugarcane spirit), sugar, and lime. Cachaca is different from rum — while both come from sugarcane, cachaca is made from fresh cane juice and rum from molasses.' },
  { id: 'food-48', category: 'food-drink', difficulty: 'medium', question: 'What style of beer originated in the Czech city of Plzen?', answer: 'Pilsner', options: ['Lager', 'Stout', 'Pilsner', 'Porter'], explanation: 'Pilsner was first brewed in Plzen (Pilsen) in 1842 by Bavarian brewer Josef Groll. The city\'s remarkably soft water contributed to the beer\'s crisp, clean character. Pilsner Urquell, still brewed there, claims to be the original.' },
  { id: 'food-49', category: 'food-drink', difficulty: 'medium', question: 'What is the fermentation process used to make sauerkraut and kimchi?', answer: 'Lacto-fermentation', options: ['Alcoholic fermentation', 'Lacto-fermentation', 'Acetic acid fermentation', 'Malolactic fermentation'], explanation: 'Lacto-fermentation uses Lactobacillus bacteria to convert sugars into lactic acid, which preserves the food and gives it its tangy flavor. This ancient preservation technique requires only salt, vegetables, and time — no vinegar.' },
  { id: 'food-50', category: 'food-drink', difficulty: 'medium', question: 'What Italian dessert literally translates to "pick me up"?', answer: 'Tiramisu', options: ['Panna cotta', 'Tiramisu', 'Zabaglione', 'Semifreddo'], explanation: 'Tiramisu ("tira mi su") was likely invented in the Veneto region of Italy in the 1960s or 1970s. It is made with ladyfinger biscuits dipped in coffee, layered with mascarpone cream, and dusted with cocoa powder.' },
  { id: 'food-51', category: 'food-drink', difficulty: 'medium', question: 'What is the highest rating a restaurant can receive from the Michelin Guide?', answer: 'Three stars', options: ['Four stars', 'Three stars', 'Five stars', 'Grand Prix'], explanation: 'Michelin awards up to three stars: one star means "a very good restaurant," two stars means "excellent cooking, worth a detour," and three stars means "exceptional cuisine, worth a special journey." The guide was created by the Michelin tire company in 1900.' },
  { id: 'food-52', category: 'food-drink', difficulty: 'medium', question: 'What Indian bread is baked in a tandoor oven?', answer: 'Naan', options: ['Chapati', 'Naan', 'Paratha', 'Roti'], explanation: 'Naan is leavened with yeast and baked by slapping it against the walls of a tandoor, a cylindrical clay oven that can reach 900°F. Chapati and roti are unleavened flatbreads cooked on a flat griddle.' },
  { id: 'food-53', category: 'food-drink', difficulty: 'medium', question: 'What cocktail is made with equal parts Campari, gin, and sweet vermouth?', answer: 'Negroni', options: ['Negroni', 'Americano', 'Aperol Spritz', 'Boulevardier'], explanation: 'The Negroni was supposedly invented in 1919 in Florence when Count Camillo Negroni asked a bartender to strengthen his Americano by replacing the soda water with gin. A Boulevardier substitutes bourbon for the gin.' },
  { id: 'food-54', category: 'food-drink', difficulty: 'medium', question: 'What is the name of the Japanese fermented soybean paste used in soup?', answer: 'Miso', options: ['Dashi', 'Miso', 'Ponzu', 'Shoyu'], explanation: 'Miso is made by fermenting soybeans with salt and a mold called koji (Aspergillus oryzae). White miso (shiro) is mild and sweet, while red miso (aka) is fermented longer and has a stronger, saltier flavor.' },
  { id: 'food-55', category: 'food-drink', difficulty: 'medium', question: 'What wine region is located in the Napa Valley?', answer: 'California', options: ['Oregon', 'Washington', 'California', 'New York'], explanation: 'Napa Valley became world-famous after the 1976 Judgment of Paris, when California wines beat French wines in a blind tasting. This event, organized by British wine merchant Steven Spurrier, shocked the wine world.' },
  { id: 'food-56', category: 'food-drink', difficulty: 'medium', question: 'What type of sugar is used to make caramel?', answer: 'White granulated sugar', options: ['Brown sugar', 'Powdered sugar', 'White granulated sugar', 'Raw sugar'], explanation: 'Caramelization occurs when sugar is heated to around 340°F, causing it to break down and develop complex flavors and a brown color. White granulated sugar is preferred because it produces the most consistent results.' },
  { id: 'food-57', category: 'food-drink', difficulty: 'medium', question: 'What spirit is used as the base of a Pisco Sour?', answer: 'Pisco', options: ['Rum', 'Cachaca', 'Pisco', 'Mezcal'], explanation: 'Pisco is a brandy made from grapes, produced in Peru and Chile (both countries claim the Pisco Sour as their own). The cocktail combines pisco with lime juice, simple syrup, egg white, and Angostura bitters.' },
  { id: 'food-58', category: 'food-drink', difficulty: 'medium', question: 'What is the name for the Japanese art of knife skills and fish cutting?', answer: 'Hocho', options: ['Sashimi', 'Hocho', 'Omakase', 'Kaiseki'], explanation: 'Hocho (or hocho-do) is the Japanese tradition of knife skills. Sushi chefs train for years to master precise cuts. The yanagiba, a long single-beveled knife, is the traditional tool for slicing sashimi in one smooth pull.' },
  { id: 'food-59', category: 'food-drink', difficulty: 'medium', question: 'What food company was founded in Switzerland in 1866 by Henri Nestle and later became a major chocolate producer?', answer: 'Nestle', options: ['Lindt', 'Nestle', 'Toblerone', 'Godiva'], explanation: 'Henri Nestle founded his company in 1866 to produce infant formula. In 1875, Nestle partnered with Daniel Peter to create the first milk chocolate, revolutionizing the confectionery industry and expanding into one of the world\'s largest food companies.' },
  { id: 'food-60', category: 'food-drink', difficulty: 'medium', question: 'What type of tea undergoes full oxidation during processing?', answer: 'Black tea', options: ['Green tea', 'White tea', 'Oolong tea', 'Black tea'], explanation: 'All true teas come from the same plant (Camellia sinensis); the difference is in processing. Black tea is fully oxidized, oolong is partially oxidized, green tea is minimally oxidized, and white tea is the least processed.' },
  { id: 'food-61', category: 'food-drink', difficulty: 'medium', question: 'What French term describes a small appetizer served before the meal, chosen by the chef?', answer: 'Amuse-bouche', options: ['Hors d\'oeuvre', 'Amuse-bouche', 'Canape', 'Entree'], explanation: 'Amuse-bouche literally means "mouth amuser." Unlike hors d\'oeuvres, which are ordered from a menu, an amuse-bouche is a complimentary bite-sized offering chosen by the chef to prepare the palate for the meal.' },
  { id: 'food-62', category: 'food-drink', difficulty: 'medium', question: 'What Korean dish is a spicy fermented vegetable side dish, most commonly made with cabbage?', answer: 'Kimchi', options: ['Bibimbap', 'Kimchi', 'Bulgogi', 'Japchae'], explanation: 'Kimchi has been a staple of Korean cuisine for over 2,000 years. There are hundreds of varieties, but the most common is baechu-kimchi (napa cabbage kimchi). It was designated a UNESCO Intangible Cultural Heritage in 2013.' },
  { id: 'food-63', category: 'food-drink', difficulty: 'medium', question: 'What is the main ingredient in the Middle Eastern dip baba ghanoush?', answer: 'Eggplant', options: ['Chickpeas', 'Eggplant', 'Tahini', 'Yogurt'], explanation: 'Baba ghanoush is made from roasted or grilled eggplant blended with tahini, lemon juice, and garlic. The smoky flavor from charring the eggplant is essential. The name roughly translates to "pampered papa" in Arabic.' },
  { id: 'food-64', category: 'food-drink', difficulty: 'medium', question: 'What country produces Gruyere cheese?', answer: 'Switzerland', options: ['France', 'Switzerland', 'Austria', 'Belgium'], explanation: 'Gruyere is named after the town of Gruyeres in the canton of Fribourg, Switzerland. It is a hard cheese aged for at least five months, known for its nutty, slightly sweet flavor, and is essential in fondue and French onion soup.' },
  { id: 'food-65', category: 'food-drink', difficulty: 'medium', question: 'What is the name of the fermented tea drink made with a SCOBY?', answer: 'Kombucha', options: ['Kefir', 'Kombucha', 'Kvass', 'Tepache'], explanation: 'Kombucha is fermented using a SCOBY (Symbiotic Culture of Bacteria and Yeast). It likely originated in Manchuria around 220 BC. The SCOBY forms a rubbery disc that ferments sweetened tea over 7-14 days.' },
  { id: 'food-66', category: 'food-drink', difficulty: 'medium', question: 'What spirit forms the base of a Gimlet?', answer: 'Gin', options: ['Vodka', 'Gin', 'Rum', 'Tequila'], explanation: 'A classic Gimlet is made with gin and lime cordial (Rose\'s Lime Juice). It was popularized by British Royal Navy officers in the 19th century as a way to prevent scurvy while making their gin ration more palatable.' },
  { id: 'food-67', category: 'food-drink', difficulty: 'medium', question: 'What cooking method involves cooking food sealed in a plastic bag in a water bath at a precise temperature?', answer: 'Sous vide', options: ['Poaching', 'Sous vide', 'Bain-marie', 'Blanching'], explanation: 'Sous vide (French for "under vacuum") was developed in the 1970s by French chef Georges Pralus. The technique allows incredibly precise temperature control, producing consistently perfect results that are difficult to achieve otherwise.' },
  { id: 'food-68', category: 'food-drink', difficulty: 'medium', question: 'What is the traditional base spirit of a Mai Tai?', answer: 'Rum', options: ['Rum', 'Vodka', 'Tequila', 'Gin'], explanation: 'The Mai Tai was created by Trader Vic (Victor Bergeron) in Oakland, California in 1944. The original recipe used aged Jamaican rum, lime, orange curacao, orgeat syrup, and rock candy syrup — much simpler than modern fruity versions.' },
  { id: 'food-69', category: 'food-drink', difficulty: 'medium', question: 'What Ethiopian ceremony involves roasting, grinding, and brewing coffee in front of guests?', answer: 'Jebena buna', options: ['Tej ceremony', 'Jebena buna', 'Kaldi ceremony', 'Injera ceremony'], explanation: 'The Ethiopian coffee ceremony, called jebena buna (named after the clay pot used to brew it), can last two to three hours and involves three rounds of coffee. Ethiopia is considered the birthplace of coffee, with the legend of the goat herder Kaldi discovering coffee beans around 850 AD.' },
  { id: 'food-70', category: 'food-drink', difficulty: 'medium', question: 'What French pastry consists of choux dough filled with cream and topped with chocolate?', answer: 'Eclair', options: ['Profiterole', 'Eclair', 'Paris-Brest', 'Religieuse'], explanation: 'The eclair was developed in France in the 19th century, possibly by Marie-Antoine Careme. The word "eclair" means "lightning" in French, possibly because of how quickly they are eaten or their shiny icing.' },
  { id: 'food-71', category: 'food-drink', difficulty: 'medium', question: 'What is the term for a wine expert who manages a restaurant\'s wine program?', answer: 'Sommelier', options: ['Vintner', 'Sommelier', 'Oenologist', 'Maitre d\''], explanation: 'The word sommelier comes from the old French "sommerier," a court official in charge of provisions. The Master Sommelier exam is considered one of the hardest professional tests in the world, with a pass rate under 10%.' },
  { id: 'food-72', category: 'food-drink', difficulty: 'medium', question: 'What type of cheese has blue veins of mold running through it?', answer: 'Blue cheese', options: ['Brie', 'Blue cheese', 'Gouda', 'Gruyere'], explanation: 'Blue cheese gets its distinctive veins from Penicillium mold cultures introduced during production. Famous varieties include Roquefort (France), Gorgonzola (Italy), and Stilton (England). Roquefort is aged in the Combalou caves of southern France.' },
  { id: 'food-73', category: 'food-drink', difficulty: 'medium', question: 'What is the primary grain used to make Japanese shochu?', answer: 'Sweet potato or barley', options: ['Rice', 'Sweet potato or barley', 'Wheat', 'Corn'], explanation: 'Shochu can be made from sweet potato (imo), barley (mugi), rice (kome), or other ingredients. Unlike sake, it is distilled rather than brewed. It is Japan\'s most consumed spirit, outselling sake domestically.' },
  { id: 'food-74', category: 'food-drink', difficulty: 'medium', question: 'What is the name of the traditional Spanish cold tomato soup?', answer: 'Gazpacho', options: ['Gazpacho', 'Salmorejo', 'Ajoblanco', 'Vichyssoise'], explanation: 'Gazpacho originated in Andalusia, southern Spain, and was originally made without tomatoes (which came from the Americas). The modern tomato-based version includes bread, olive oil, vinegar, garlic, and raw vegetables.' },
  { id: 'food-75', category: 'food-drink', difficulty: 'medium', question: 'What is the name of the Italian cured meat made from pork belly?', answer: 'Pancetta', options: ['Prosciutto', 'Pancetta', 'Coppa', 'Bresaola'], explanation: 'Pancetta is cured with salt and spices but is not smoked, which distinguishes it from American bacon. Prosciutto is made from the hind leg, while pancetta comes from the belly (pancia means "belly" in Italian).' },
  { id: 'food-76', category: 'food-drink', difficulty: 'medium', question: 'What country is the origin of the cocktail known as the Dark \'n\' Stormy?', answer: 'Bermuda', options: ['Jamaica', 'Bermuda', 'Cuba', 'Barbados'], explanation: 'The Dark \'n\' Stormy is made with Gosling\'s Black Seal rum and ginger beer. Gosling\'s has actually trademarked the cocktail name, making it one of the few trademarked mixed drinks. It must be made with their rum to bear the name.' },
  { id: 'food-77', category: 'food-drink', difficulty: 'medium', question: 'What type of pasta is shaped like little ears?', answer: 'Orecchiette', options: ['Farfalle', 'Orecchiette', 'Conchiglie', 'Rotelle'], explanation: 'Orecchiette ("little ears") is the signature pasta of Puglia in southern Italy. Each piece is traditionally shaped by hand by pressing the dough with a knife and turning it over the thumb. It pairs well with broccoli rabe.' },
  { id: 'food-78', category: 'food-drink', difficulty: 'medium', question: 'What does IPA stand for in beer terminology?', answer: 'India Pale Ale', options: ['India Pale Ale', 'International Pale Ale', 'Imperial Pale Ale', 'Irish Pale Ale'], explanation: 'IPAs were originally brewed in England in the late 1700s with extra hops to survive the long sea voyage to India. The additional hops acted as a natural preservative. Modern American IPAs tend to be much hoppier than the original British style.' },
  { id: 'food-79', category: 'food-drink', difficulty: 'medium', question: 'What food holiday is celebrated in the United States on the fourth Thursday of November?', answer: 'Thanksgiving', options: ['Thanksgiving', 'National Turkey Day', 'Harvest Festival', 'Fall Feast Day'], explanation: 'Thanksgiving became a national holiday in 1863 when Abraham Lincoln proclaimed it during the Civil War. Americans consume approximately 46 million turkeys on Thanksgiving each year.' },
  { id: 'food-80', category: 'food-drink', difficulty: 'medium', question: 'What herb is the key ingredient in traditional pesto alla Genovese?', answer: 'Basil', options: ['Parsley', 'Basil', 'Oregano', 'Cilantro'], explanation: 'Pesto alla Genovese is made with fresh basil, garlic, pine nuts, Parmigiano-Reggiano, Pecorino, and olive oil. It originated in Genoa, and the word "pesto" comes from "pestare," meaning to pound or crush in a mortar.' },
  { id: 'food-81', category: 'food-drink', difficulty: 'medium', question: 'What is the name of the coffee brewing method that uses pressure to force hot water through finely-ground coffee?', answer: 'Espresso', options: ['French press', 'Pour over', 'Espresso', 'Percolator'], explanation: 'Espresso was invented in Italy in the early 20th century. Angelo Moriondo patented an early steam-driven machine in 1884, but Luigi Bezzera and Desiderio Pavoni refined and commercialized espresso machines in the early 1900s.' },
  { id: 'food-82', category: 'food-drink', difficulty: 'medium', question: 'What famous chef pioneered the "New Nordic Cuisine" movement at his restaurant Noma?', answer: 'Rene Redzepi', options: ['Rene Redzepi', 'Magnus Nilsson', 'Heston Blumenthal', 'Massimo Bottura'], explanation: 'Rene Redzepi opened Noma in Copenhagen in 2003 and was named the world\'s best restaurant multiple times. He championed foraging, local ingredients, and fermentation, transforming Scandinavian cuisine\'s global reputation. Noma closed at the end of 2024.' },
  { id: 'food-83', category: 'food-drink', difficulty: 'medium', question: 'What is the term for a cocktail served without ice, strained into a glass?', answer: 'Straight up', options: ['Neat', 'Straight up', 'On the rocks', 'Dry'], explanation: 'A drink served "straight up" (or just "up") is shaken or stirred with ice then strained into a chilled glass without ice. "Neat" means served at room temperature with no ice and no mixing. These terms are frequently confused.' },
  { id: 'food-84', category: 'food-drink', difficulty: 'medium', question: 'What region of Italy is known for balsamic vinegar?', answer: 'Modena', options: ['Tuscany', 'Modena', 'Sicily', 'Piedmont'], explanation: 'Traditional balsamic vinegar of Modena (Aceto Balsamico Tradizionale) is aged for a minimum of 12 years in a series of progressively smaller wooden barrels. True traditional balsamic can cost over $100 for a small bottle.' },
  { id: 'food-85', category: 'food-drink', difficulty: 'medium', question: 'What Mexican holiday on November 1-2 is associated with sugar skulls and pan de muerto?', answer: 'Day of the Dead', options: ['Cinco de Mayo', 'Day of the Dead', 'Las Posadas', 'Mexican Independence Day'], explanation: 'Dia de los Muertos (Day of the Dead) honors deceased loved ones with altars (ofrendas) featuring their favorite foods. Pan de muerto is a sweet bread decorated with bone-shaped dough, and sugar skulls (calaveras) bear the names of the departed.' },
  { id: 'food-86', category: 'food-drink', difficulty: 'medium', question: 'What is the primary ingredient in the Thai sauce called nam pla?', answer: 'Fish', options: ['Soy', 'Fish', 'Oyster', 'Tamarind'], explanation: 'Nam pla is Thai fish sauce, made by fermenting fish (usually anchovies) with salt for months to years. Fish sauce is essential to Southeast Asian cooking, providing umami depth. The Romans had a similar condiment called garum.' },
  { id: 'food-87', category: 'food-drink', difficulty: 'medium', question: 'What spirit is the base of a classic Daiquiri?', answer: 'White rum', options: ['White rum', 'Vodka', 'Tequila', 'Cachaca'], explanation: 'The Daiquiri was created in Cuba around 1900 and is named after a beach near Santiago. The classic version is simply white rum, lime juice, and sugar — a far cry from the frozen fruit versions popular today.' },
  { id: 'food-88', category: 'food-drink', difficulty: 'medium', question: 'What country is associated with the wine classification system of AOC (Appellation d\'Origine Controlee)?', answer: 'France', options: ['Italy', 'France', 'Spain', 'Germany'], explanation: 'France established the AOC system in 1935 to regulate wine production, guaranteeing geographic origin and production methods. Italy has a similar DOC/DOCG system, and Spain uses DO/DOCa. The EU later adopted the broader PDO designation.' },
  { id: 'food-89', category: 'food-drink', difficulty: 'medium', question: 'What is the world\'s oldest known alcoholic beverage?', answer: 'Mead', options: ['Beer', 'Wine', 'Mead', 'Sake'], explanation: 'Mead, made from fermented honey and water, dates back to at least 7000 BC based on chemical analysis of ancient pottery. It predates both grape wine and grain beer and was consumed across Africa, Europe, and Asia.' },
  { id: 'food-90', category: 'food-drink', difficulty: 'hard', question: 'What cocktail was created at Harry\'s Bar in Venice and combines Prosecco with peach puree?', answer: 'Bellini', options: ['Kir Royale', 'Bellini', 'French 75', 'Mimosa'], explanation: 'The Bellini was created at Harry\'s Bar in Venice by Giuseppe Cipriani around 1948. He named it after the 15th-century Venetian painter Giovanni Bellini because the drink\'s pink color reminded him of a Bellini painting.' },
  { id: 'food-91', category: 'food-drink', difficulty: 'hard', question: 'What is the Maillard reaction?', answer: 'A chemical reaction between amino acids and sugars that produces browning and flavor', options: ['The process of sugar crystallization', 'A chemical reaction between amino acids and sugars that produces browning and flavor', 'The breakdown of fats at high temperatures', 'The fermentation of starches into alcohol'], explanation: 'The Maillard reaction, named after French chemist Louis-Camille Maillard who described it in 1912, is responsible for the flavors of browned meat, toasted bread, roasted coffee, and many other cooked foods. It is different from caramelization, which involves only sugars.' },
  { id: 'food-92', category: 'food-drink', difficulty: 'hard', question: 'What is the name of the traditional French cooking term for a mixture of diced onion, celery, and carrot?', answer: 'Mirepoix', options: ['Bouquet garni', 'Mirepoix', 'Brunoise', 'Battuto'], explanation: 'Mirepoix is named after the Duke of Levis-Mirepoix, an 18th-century French nobleman. The standard ratio is 2:1:1 (onion:celery:carrot). The Italian equivalent is "soffritto" and the Cajun "Holy Trinity" replaces the carrot with bell pepper.' },
  { id: 'food-93', category: 'food-drink', difficulty: 'hard', question: 'What type of barrel must Scotch whisky be aged in?', answer: 'Oak', options: ['Cherry wood', 'Maple', 'Oak', 'Pine'], explanation: 'Scotch whisky must be aged in oak casks for a minimum of three years in Scotland. Many distillers use ex-bourbon barrels from America (which can only be used once for bourbon) or ex-sherry casks from Spain, each imparting different flavors.' },
  { id: 'food-94', category: 'food-drink', difficulty: 'hard', question: 'What Japanese term describes the "fifth taste" identified by Kikunae Ikeda in 1908?', answer: 'Umami', options: ['Dashi', 'Umami', 'Kokumi', 'Shibui'], explanation: 'Kikunae Ikeda identified umami while studying the taste of kombu seaweed broth. He discovered that glutamate was responsible and went on to create MSG (monosodium glutamate). Umami was not officially recognized as a basic taste by Western science until 1985.' },
  { id: 'food-95', category: 'food-drink', difficulty: 'hard', question: 'What is the name of the New Orleans sandwich served on French bread with roast beef and gravy?', answer: 'Po\' boy', options: ['Muffuletta', 'Po\' boy', 'Hoagie', 'Hero'], explanation: 'The po\' boy sandwich originated in New Orleans in 1929 when Bennie and Clovis Martin served free sandwiches to striking streetcar workers, calling them "poor boys." The muffuletta is a different New Orleans sandwich served on round Italian bread with olive salad.' },
  { id: 'food-96', category: 'food-drink', difficulty: 'hard', question: 'What wine term describes the scent a wine develops from aging, as opposed to its primary fruit aromas?', answer: 'Bouquet', options: ['Nose', 'Bouquet', 'Terroir', 'Finish'], explanation: 'In wine terminology, "aroma" refers to scents from the grape and fermentation (primary and secondary), while "bouquet" specifically describes the complex scents that develop during bottle aging (tertiary aromas). These can include leather, tobacco, earth, and dried fruit.' },
  { id: 'food-97', category: 'food-drink', difficulty: 'hard', question: 'What is the name for the method of adding Champagne\'s signature bubbles through secondary fermentation in the bottle?', answer: 'Methode Champenoise', options: ['Charmat method', 'Methode Champenoise', 'Pet-nat', 'Transfer method'], explanation: 'Methode Champenoise (or methode traditionnelle) involves adding yeast and sugar to still wine in the bottle to create a secondary fermentation. The Charmat method does this in tanks and is less expensive. By EU law, only Champagne producers can call it methode champenoise.' },
  { id: 'food-98', category: 'food-drink', difficulty: 'hard', question: 'What Spanish technique involves serving small dishes of food alongside drinks?', answer: 'Tapas', options: ['Pintxos', 'Tapas', 'Raciones', 'Merienda'], explanation: 'Tapas originated in Andalusia and the word means "lids" or "covers." Legend says bartenders placed small plates of food over glasses to keep flies out. Pintxos (or pinchos) are the Basque Country\'s version, typically served on bread with a toothpick.' },
  { id: 'food-99', category: 'food-drink', difficulty: 'hard', question: 'What famous New York restaurant, established in 1837, is considered America\'s first fine dining restaurant?', answer: 'Delmonico\'s', options: ['Delmonico\'s', 'Peter Luger', 'The Old Ebbitt Grill', 'Antoine\'s'], explanation: 'Delmonico\'s was established in 1837 at 56 Beaver Street (with a predecessor cafe dating to 1827) and pioneered American fine dining. Dishes like Lobster Newburg, Baked Alaska, and Delmonico steak were created there. Antoine\'s in New Orleans (1840) is another historically significant early American restaurant.' },
  { id: 'food-100', category: 'food-drink', difficulty: 'hard', question: 'What is the name of the Italian egg-and-cheese sauce used in carbonara?', answer: 'There is no special name — it is simply eggs, Pecorino Romano, and black pepper', options: ['Alfredo', 'Carbonara sauce', 'There is no special name — it is simply eggs, Pecorino Romano, and black pepper', 'Cacio e pepe'], explanation: 'Authentic carbonara uses raw eggs, Pecorino Romano (not Parmesan), guanciale (not bacon), and black pepper — no cream. The heat from the pasta cooks the eggs into a silky sauce. Adding cream to carbonara is considered a culinary sin in Italy.' },
  { id: 'food-101', category: 'food-drink', difficulty: 'hard', question: 'What drink matches the earliest published definition of a cocktail (spirit, sugar, water, and bitters) from 1806?', answer: 'The Old Fashioned', options: ['The Old Fashioned', 'The Sazerac', 'The Mint Julep', 'The Sling'], explanation: 'The Old Fashioned is widely considered the original cocktail, matching the first published definition of "cocktail" (spirit, sugar, water, bitters) from 1806. Historian David Wondrich has noted that the Sazerac, often claimed as America\'s first cocktail, actually dates to the 1880s, much later than commonly believed.' },
  { id: 'food-102', category: 'food-drink', difficulty: 'hard', question: 'What is the term for the practice of adding a small amount of older sherry to younger sherry in a fractional blending system?', answer: 'Solera', options: ['Assemblage', 'Solera', 'Coupage', 'Racking'], explanation: 'The solera system uses stacked rows of barrels, with the oldest on the bottom (the "solera") and youngest on top. Wine is drawn from the bottom barrels and replenished from above, ensuring consistency. Some soleras date back over a century.' },
  { id: 'food-103', category: 'food-drink', difficulty: 'hard', question: 'What French term describes the unique environmental factors (soil, climate, geography) that affect a wine\'s character?', answer: 'Terroir', options: ['Cepage', 'Terroir', 'Appellation', 'Cru'], explanation: 'Terroir encompasses soil composition, drainage, elevation, sun exposure, and microclimate. The French believe terroir is the most important factor in wine quality, which is why their classification systems are based on geography rather than grape variety.' },
  { id: 'food-104', category: 'food-drink', difficulty: 'hard', question: 'What is the name of the bitter orange liqueur used in a classic Margarita and Cosmopolitan?', answer: 'Cointreau', options: ['Grand Marnier', 'Cointreau', 'Curacao', 'Chartreuse'], explanation: 'Cointreau is a brand of triple sec (a type of orange liqueur) first produced in 1875 in Angers, France. Grand Marnier is a cognac-based orange liqueur, while Cointreau is a neutral-spirit-based one. Both are types of curacao.' },
  { id: 'food-105', category: 'food-drink', difficulty: 'hard', question: 'What is the maximum number of Michelin stars a restaurant can hold?', answer: 'Three', options: ['Three', 'Four', 'Five', 'Six'], explanation: 'As of recent counts, there are only around 140 three-star restaurants in the world. Joel Robuchon held the record for most Michelin stars of any chef, with 32 stars across his restaurant group at his peak.' },
  { id: 'food-106', category: 'food-drink', difficulty: 'hard', question: 'What is the name of the poisonous compound found in raw kidney beans?', answer: 'Phytohaemagglutinin', options: ['Solanine', 'Phytohaemagglutinin', 'Oxalic acid', 'Cyanide'], explanation: 'Phytohaemagglutinin (a type of lectin) in raw or undercooked red kidney beans can cause severe nausea, vomiting, and diarrhea. Boiling the beans for at least 10 minutes destroys the toxin. Slow cookers may not reach high enough temperatures to neutralize it.' },
  { id: 'food-107', category: 'food-drink', difficulty: 'hard', question: 'What is the term for the foam on top of an espresso shot?', answer: 'Crema', options: ['Froth', 'Crema', 'Mousse', 'Schiuma'], explanation: 'Crema is the golden-brown foam that forms on top of a properly extracted espresso shot. It is created by the emulsification of oils and CO2 under the high pressure (9 bars) of an espresso machine. Its quality is often used to judge the shot.' },
  { id: 'food-108', category: 'food-drink', difficulty: 'hard', question: 'What is the traditional garnish on a Gibson cocktail that distinguishes it from a Martini?', answer: 'Cocktail onion', options: ['Olive', 'Lemon twist', 'Cocktail onion', 'Cherry'], explanation: 'A Gibson is identical to a Martini in composition (gin and dry vermouth) but garnished with a pickled cocktail onion instead of an olive or lemon twist. Its exact origin is disputed, with several people named Gibson claiming credit.' },
  { id: 'food-109', category: 'food-drink', difficulty: 'hard', question: 'What is the name of the Japanese multi-course haute cuisine tradition?', answer: 'Kaiseki', options: ['Omakase', 'Kaiseki', 'Kappo', 'Washoku'], explanation: 'Kaiseki originated from the simple meals served during the Japanese tea ceremony. Modern kaiseki consists of many small, beautifully presented courses that showcase seasonal ingredients. Omakase ("I\'ll leave it to you") is a chef\'s-choice format, not a specific cuisine style.' },
  { id: 'food-110', category: 'food-drink', difficulty: 'hard', question: 'What is the name of the worm that is sometimes found in bottles of mezcal?', answer: 'Gusano', options: ['Gusano', 'Tequila worm', 'Agave worm', 'Maguey worm'], explanation: 'The gusano (actually a moth larva, not a worm) is found in some mezcal bottles, never in tequila. It was a marketing gimmick started in the 1950s. There are two types: the red gusano rojo (from the agave heart) and the white gusano de maguey.' },
  { id: 'food-111', category: 'food-drink', difficulty: 'hard', question: 'What does the term "cuvee" mean in winemaking?', answer: 'A blend or specific batch of wine', options: ['A single vineyard', 'A blend or specific batch of wine', 'The first pressing', 'A vintage year'], explanation: 'Cuvee comes from the French word "cuve" meaning vat or tank. In Champagne, it specifically refers to the juice from the first pressing of grapes. More broadly, it designates a particular blend or a winery\'s prestige bottling.' },
  { id: 'food-112', category: 'food-drink', difficulty: 'hard', question: 'What is the name of the traditional Oaxacan Mexican sauce made with chocolate and chili peppers?', answer: 'Mole', options: ['Adobo', 'Mole', 'Salsa macha', 'Pipian'], explanation: 'Mole (from the Nahuatl "molli" meaning sauce) can contain 20 or more ingredients, including various chilies, chocolate, spices, nuts, and seeds. There are seven main varieties of Oaxacan mole, with mole negro being the most complex and revered.' },
  { id: 'food-113', category: 'food-drink', difficulty: 'hard', question: 'What is the process of removing sediment from Champagne called?', answer: 'Disgorgement', options: ['Riddling', 'Disgorgement', 'Racking', 'Fining'], explanation: 'Disgorgement (degorgement) follows riddling (remuage), where bottles are gradually tilted to collect sediment in the neck. The neck is then frozen, the cap removed, and pressure expels the frozen sediment plug. The bottle is topped up and corked.' },
  { id: 'food-114', category: 'food-drink', difficulty: 'hard', question: 'What is the name of the classic French sauce made from a brown roux and brown stock?', answer: 'Espagnole', options: ['Demi-glace', 'Espagnole', 'Bordelaise', 'Veloute'], explanation: 'Espagnole is one of the five French mother sauces codified by Escoffier. When espagnole is combined with additional stock and reduced by half, it becomes demi-glace, which is the base for many other classic French sauces like bordelaise.' },
  { id: 'food-115', category: 'food-drink', difficulty: 'hard', question: 'What country produces Tokaji, one of the world\'s most famous sweet wines?', answer: 'Hungary', options: ['Austria', 'Hungary', 'Germany', 'Romania'], explanation: 'Tokaji (also spelled Tokay) comes from the Tokaj region of northeastern Hungary. Louis XIV of France called it "the wine of kings, the king of wines." Tokaji Aszu is made from botrytized (noble rot) grapes, creating an intensely sweet and complex wine.' },
  { id: 'food-116', category: 'food-drink', difficulty: 'hard', question: 'What is the name of the Italian rice dish made by slowly adding broth and stirring?', answer: 'Risotto', options: ['Arancini', 'Risotto', 'Polenta', 'Pilaf'], explanation: 'Risotto originated in northern Italy, where short-grain rice varieties like Arborio, Carnaroli, and Vialone Nano are grown. The constant stirring releases starch from the rice, creating risotto\'s signature creamy texture without adding cream.' },
  { id: 'food-117', category: 'food-drink', difficulty: 'hard', question: 'What type of wood is traditionally used to smoke Scottish salmon?', answer: 'Oak', options: ['Hickory', 'Mesquite', 'Oak', 'Cherry'], explanation: 'Traditional Scottish smoked salmon is cold-smoked over oak for 12-48 hours at temperatures below 86°F. London cure uses oak shavings and produces a milder flavor, while Scottish Highland smokeries often use whisky barrel staves for a distinctive character.' },
  { id: 'food-118', category: 'food-drink', difficulty: 'hard', question: 'What pioneer of molecular gastronomy opened the restaurant elBulli in Spain?', answer: 'Ferran Adria', options: ['Ferran Adria', 'Heston Blumenthal', 'Grant Achatz', 'Massimo Bottura'], explanation: 'Ferran Adria transformed elBulli in Catalonia into the world\'s most influential restaurant, pioneering techniques like spherification and culinary foam. The restaurant closed in 2011 after being named the world\'s best restaurant a record five times.' },
  { id: 'food-119', category: 'food-drink', difficulty: 'hard', question: 'What is the difference between single malt and blended Scotch whisky?', answer: 'Single malt is from one distillery using only malted barley; blended combines whiskies from multiple distilleries', options: ['Single malt is older; blended is younger', 'Single malt uses copper stills; blended uses steel', 'Single malt is from one distillery using only malted barley; blended combines whiskies from multiple distilleries', 'Single malt is unpeated; blended is peated'], explanation: '"Single" means from a single distillery, and "malt" means made entirely from malted barley. Blended Scotch combines malt whiskies from different distilleries with grain whisky. Blends account for about 90% of Scotch sold worldwide.' },
  { id: 'food-120', category: 'food-drink', difficulty: 'hard', question: 'What is the name of the toxic pufferfish delicacy served in Japan?', answer: 'Fugu', options: ['Sashimi', 'Fugu', 'Unagi', 'Shirako'], explanation: 'Fugu contains tetrodotoxin, which is 1,200 times more poisonous than cyanide and has no known antidote. Chefs must undergo years of training and pass rigorous tests to receive a license to prepare it. Despite precautions, a few deaths occur each year.' },
  { id: 'food-121', category: 'food-drink', difficulty: 'hard', question: 'What is the name of the cocktail made with absinthe that involves dripping water over a sugar cube?', answer: 'Absinthe Drip', options: ['Corpse Reviver', 'Death in the Afternoon', 'Absinthe Drip', 'Green Fairy'], explanation: 'The traditional absinthe service (louche) involves placing a slotted spoon with a sugar cube over a glass of absinthe and slowly dripping ice-cold water over it. The water causes the essential oils to come out of solution, turning the drink milky (the louche effect).' },
  { id: 'food-122', category: 'food-drink', difficulty: 'hard', question: 'What cheese is traditionally used in a Greek salad?', answer: 'Feta', options: ['Halloumi', 'Feta', 'Kasseri', 'Mizithra'], explanation: 'A traditional Greek salad (horiatiki) contains tomatoes, cucumber, onion, olives, feta cheese, and olive oil — no lettuce. The EU ruled in 2002 that only cheese made in specific Greek regions from sheep\'s milk (with up to 30% goat\'s milk) can be called feta.' },
  { id: 'food-123', category: 'food-drink', difficulty: 'hard', question: 'What is the process of clarifying butter by removing milk solids and water called?', answer: 'Making ghee', options: ['Rendering', 'Making ghee', 'Tempering', 'Emulsifying'], explanation: 'Ghee is clarified butter taken a step further — the milk solids are browned before straining, giving it a nutty flavor. It has been used in Indian cooking for thousands of years and has a higher smoke point (485°F) than regular butter (350°F).' },
  { id: 'food-124', category: 'food-drink', difficulty: 'hard', question: 'What cocktail was invented at the Raffles Hotel in Singapore around 1915?', answer: 'Singapore Sling', options: ['Singapore Sling', 'Tiki Punch', 'Zombie', 'Jungle Bird'], explanation: 'The Singapore Sling was created by bartender Ngiam Tong Boon at the Raffles Hotel\'s Long Bar. The original recipe has been debated, but it generally includes gin, cherry liqueur (Heering), Cointreau, Benedictine, pineapple juice, lime, grenadine, and bitters.' },
  { id: 'food-125', category: 'food-drink', difficulty: 'hard', question: 'What does the term "biodynamic" mean in winemaking?', answer: 'A holistic farming approach based on Rudolf Steiner\'s agricultural philosophy', options: ['Wine made without any additives', 'A holistic farming approach based on Rudolf Steiner\'s agricultural philosophy', 'Wine fermented with wild yeasts only', 'Grapes grown without irrigation'], explanation: 'Biodynamic farming, developed from Rudolf Steiner\'s 1924 lectures, treats the vineyard as a self-sustaining ecosystem and follows a planting calendar based on astronomical cycles. It goes beyond organic farming and includes practices like burying cow horns filled with manure.' },
]
